// searchQueue builds a queue whose resolver answers only the given sources and
// whose FetchGate runs on the injectable clock (deterministic spacing slots).
func searchQueue(t *testing.T, srcs map[string]sdk.MetadataSource, clock func() time.Time) (*Queue, *store.Store) {
	t.Helper()
	s, reg := queueTestStore(t)
	q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{})
	q.resolve = mapResolver(srcs).resolver()
	if clock != nil {
		q.deps.FetchGate = newFetchGate(clock)
	}
	return q, s
}

// TestSearchSource covers the identify overlay's search passthrough (identify-
// match-override): served order verbatim with convention-field maps, and the
// error paths — the unsupported sentinel (direct and across a text round-trip
// seam), the manager's unknown-plugin error, and a failed fetch.
func TestSearchSource(t *testing.T) {
	ctx := context.Background()
	live := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		_, _ = w.Write([]byte(`[]`))
	}))
	t.Cleanup(live.Close)

	full := &metadatav1.SearchCandidate{
		ExternalId: "378", Title: "Aria the Animation", Kind: "tv",
		RussianTitle: proto.String("Ария: Анимация"), Year: proto.Int32(2005),
		Episodes: proto.Int32(13), Poster: proto.String("https://shikimori.io/p.jpg"),
	}
	minimal := &metadatav1.SearchCandidate{ExternalId: "40709", Title: "Wake Up, Aria!", Kind: "ova"}

	cases := []struct {
		name     string
		srcs     map[string]sdk.MetadataSource
		checkErr func(t *testing.T, err error)
		want     []map[string]any
	}{
		{
			name: "order_and_fields_verbatim",
			srcs: map[string]sdk.MetadataSource{"shikimori": &searchSrc{
				spec:  &metadatav1.RequestSpec{Method: "GET", UrlTemplate: live.URL + "/search"},
				cands: []*metadatav1.SearchCandidate{full, minimal},
			}},
			want: []map[string]any{
				{"external_id": "378", "title": "Aria the Animation", "kind": "tv",
					"russian_title": "Ария: Анимация", "year": int32(2005), "episodes": int32(13),
					"poster": "https://shikimori.io/p.jpg"},
				{"external_id": "40709", "title": "Wake Up, Aria!", "kind": "ova"},
			},
		},
		{
			name: "unsupported_sentinel_direct",
			srcs: map[string]sdk.MetadataSource{"shikimori": &searchSrc{specErr: sdk.ErrSearchUnsupported}},
			checkErr: func(t *testing.T, err error) {
				if !errors.Is(err, sdk.ErrSearchUnsupported) {
					t.Fatalf("err = %v, want ErrSearchUnsupported (errors.Is)", err)
				}
			},
		},
		{
			name: "unsupported_sentinel_across_text_seam",
			srcs: map[string]sdk.MetadataSource{"shikimori": &searchSrc{
				specErr: errors.New(sdk.ErrSearchUnsupported.Error()), // a gRPC status round-trip
			}},
			checkErr: func(t *testing.T, err error) {
				if !errors.Is(err, sdk.ErrSearchUnsupported) {
					t.Fatalf("err = %v, want ErrSearchUnsupported re-wrapped from the seam text", err)
				}
			},
		},
		{
			name: "unknown_plugin_from_the_manager",
			srcs: map[string]sdk.MetadataSource{},
			checkErr: func(t *testing.T, err error) {
				if err == nil {
					t.Fatal("an unknown plugin must error from the manager")
				}
			},
		},
		{
			name: "failed_fetch_errors",
			srcs: map[string]sdk.MetadataSource{"shikimori": &searchSrc{
				spec: &metadatav1.RequestSpec{Method: "GET", UrlTemplate: "http://127.0.0.1:1/search"},
			}},
			checkErr: func(t *testing.T, err error) {
				if err == nil {
					t.Fatal("a failed fetch must error (the api maps it to the canonical upstream answer)")
				}
			},
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			q, _ := searchQueue(t, tc.srcs, nil)
			cands, err := q.SearchSource(ctx, "shikimori", "aria", "")
			if tc.checkErr != nil {
				tc.checkErr(t, err)
				return
			}
			if err != nil {
				t.Fatalf("SearchSource: %v", err)
			}
			if !reflect.DeepEqual(cands, tc.want) {
				t.Fatalf("candidates = %v, want %v", cands, tc.want)
			}
		})
	}
}

// TestSearchSourceGateSpacing pins the budget share (identify-match-override):
// the interactive fetch lands on the SAME per-plugin slot the sweeps use — the
// second send for a plugin is spaced at least its spec's min_interval_ms after
// the first. The fixed clock books deterministic slots; the gate's wait is a
// real timer, so the second call completes and the slot shows the spacing.
func TestSearchSourceGateSpacing(t *testing.T) {
	ctx := context.Background()
	t0 := time.Date(2026, 10, 22, 9, 0, 0, 0, time.UTC)
	live := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		_, _ = w.Write([]byte(`[]`))
	}))
	t.Cleanup(live.Close)

	q, _ := searchQueue(t, map[string]sdk.MetadataSource{"shikimori": &searchSrc{
		spec: &metadatav1.RequestSpec{Method: "GET", UrlTemplate: live.URL + "/search", MinIntervalMs: 700},
	}}, func() time.Time { return t0 })

	for i := 0; i < 2; i++ {
		if _, err := q.SearchSource(ctx, "shikimori", "aria", ""); err != nil {
			t.Fatalf("SearchSource #%d: %v", i+1, err)
		}
	}
	g := q.deps.FetchGate
	g.mu.Lock()
	last, seen := g.last["shikimori"]
	g.mu.Unlock()
	if !seen {
		t.Fatal("the interactive fetch never booked a gate slot")
	}
	if want := t0.Add(700 * time.Millisecond); !last.Equal(want) {
		t.Fatalf("gate slot = %v, want %v (the second send spaced a full interval after the first)", last, want)
	}
}

